const double kB = 1.0;
std::mt19937 rng(std::random_device{}());
std::size_t n = velocities.size();
for (std::size_t i = 0; i < n; ++i) {
    double sigma = std::sqrt(kB * temperature / masses[i]);
    std::normal_distribution<double> nd(0.0, sigma);
    velocities[i].x = nd(rng);
    velocities[i].y = nd(rng);
    velocities[i].z = nd(rng);
}
vec3 p_total{0.0, 0.0, 0.0};
double totalMass = 0.0;
for (std::size_t i = 0; i < n; ++i) {
    p_total.x += masses[i] * velocities[i].x;
    p_total.y += masses[i] * velocities[i].y;
    p_total.z += masses[i] * velocities[i].z;
    totalMass += masses[i];
}
if (totalMass != 0.0) {
    vec3 v_com{p_total.x / totalMass, p_total.y / totalMass, p_total.z / totalMass};
    for (std::size_t i = 0; i < n; ++i) {
        velocities[i].x -= v_com.x;
        velocities[i].y -= v_com.y;
        velocities[i].z -= v_com.z;
    }
}

